ROOT=Path(__file__).parent
DATE='2026-10-04'
VERSION='1.0.0'
sources=[]; rules=[]; profiles=[]
def source(id,title,url,status='verified-content',summary='',limitations='',section=''):
    sources.append(dict(id=id,title=title,url=url,publisher=url.split('/')[2] if url.startswith('https:') else 'Creative AI',authority='primary' if url.startswith('https:') else 'editorial',accessStatus=status,accessCheckedAt=DATE,verifiedAt=DATE if status=='verified-content' else None,sourceVersion='page observed '+DATE,section=section,summary=summary,limitations=limitations))
def rule(id,tier,sourceIds,statement,check=None,rationale='',limits='',status=None):
    rules.append(dict(id=id,version=VERSION,tier=tier,severity={'mandatory':'error','official-guidance':'warning','heuristic':'advisory'}[tier],sourceIds=sourceIds,statement=statement,scope={'profileIds':[]},check=check or {'method':'rendered-review'},verifiedAt=DATE if status!='unknown' else None,versionDate=DATE,confidence='high' if tier=='mandatory' else 'medium',evidenceStatus=status or ('editorial-heuristic' if tier=='heuristic' else 'verified-primary'),rationale=rationale or statement,limits=limits or 'Applies only to the attached placement and asset slot; not a universal platform rule.'))
def profile(id,family,platform,placement,assetType,name,assets=None,native=None,ruleIds=None,status='included',unknowns=None,inputs=None,notes='',channel='paid',publisher=None,market='global',use=''):
    profiles.append(dict(id=id,version=VERSION,family=family,channel=channel,platform=platform,publisher=publisher or platform,placement=placement,assetType=assetType,name=name,market=market,coverageStatus=status,verifiedAt=DATE,assets=assets or [],nativeFields=native or [],ruleIds=(ruleIds or [])+['hierarchy','legibility','spacing','message-focus','copy-image','information-flow','exact-copy'],unknowns=unknowns or [],requiredJobInputs=inputs or [],notes=notes,useCase=use or name,certification='none; numeric checks alone do not establish publisher acceptance'))
def asset(slot='artwork',role='complete-static-artwork',text='allowed',required=True):
    return dict(slot=slot,role=role,embeddedText=text,required=required)
def field(id,required=None,role='native-copy'):
    return dict(id=id,required=required,role=role,embedded=False)
def check(method,slot=None,**kw):
    return dict(method=method,**({'slot':slot} if slot else {}),**kw)
